import { readFile, writeFile } from 'node:fs/promises';
import { createHash } from 'node:crypto';

// Preserve the exact, unmodified official bytes, including CRLF. No schema rewriting.
const names = ['DPS_v1.01.xsd', 'NFSe_v1.01.xsd', 'pedRegEvento_v1.01.xsd',
  'tiposComplexos_v1.01.xsd', 'tiposEventos_v1.01.xsd', 'tiposSimples_v1.01.xsd', 'xmldsig-core-schema.xsd'];
const entries = [];
for (const name of names) {
  const bytes = await readFile(new URL(`./prodrest-20261020/${name}`, import.meta.url));
  entries.push(`  ${JSON.stringify(name)}: ${JSON.stringify({
    sha256: createHash('sha256').update(bytes).digest('hex'), base64: bytes.toString('base64'),
  })},`);
}
await writeFile(new URL('./homologation.generated.ts', import.meta.url),
  '// GENERATED by generate-homologation-bundle.mjs from original official XSDs; do not edit.\n' +
  '// https://www.gov.br/nfse/pt-br/biblioteca/documentacao-tecnica/producao-restrita/esquemas_prod_restrita_20261020.zip\n' +
  `export const HOMOLOGATION_SCHEMAS = {\n${entries.join('\n')}\n} as const;\n`);
